class Ctor:
    __slots__ = ("name", "args")

    def __init__(self, name: str, *args):
        self.name = name
        self.args = list(args)


class Seq:
    __slots__ = ("items",)

    def __init__(self, items):
        self.items = list(items)


def q(s: str) -> str:
